--
-- Table structure for table `pricing_records`
--

DROP TABLE IF EXISTS `pricing_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pricing_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sku` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `purchaseCost` decimal(12,2) NOT NULL DEFAULT '0.00',
  `weightKg` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `lengthCm` decimal(10,2) NOT NULL DEFAULT '0.00',
  `widthCm` decimal(10,2) NOT NULL DEFAULT '0.00',
  `heightCm` decimal(10,2) NOT NULL DEFAULT '0.00',
  `sellPrice` decimal(12,2) NOT NULL DEFAULT '0.00',
  `sellPriceRub` decimal(12,2) NOT NULL DEFAULT '0.00',
  `exchangeRate` decimal(10,6) NOT NULL DEFAULT '0.086200',
  `labelFee` decimal(10,2) NOT NULL DEFAULT '2.00',
  `commissionRate` decimal(6,4) NOT NULL DEFAULT '0.1200',
  `agentRate` decimal(6,4) NOT NULL DEFAULT '0.0350',
  `withdrawRate` decimal(6,4) NOT NULL DEFAULT '0.0120',
  `country` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vendor` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `channelId` int DEFAULT NULL,
  `channelName` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipMode` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logistics` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shippingFee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `billWeightKg` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `grossProfit` decimal(12,2) NOT NULL DEFAULT '0.00',
  `netProfit` decimal(12,2) NOT NULL DEFAULT '0.00',
  `profitRate` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `freightProfitRatio` decimal(10,4) NOT NULL DEFAULT '0.0000',
  `markup35` decimal(12,2) NOT NULL DEFAULT '0.00',
  `supplyUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `retailUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `userId` int DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `categoryPath` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imageUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `markupRate` decimal(6,4) NOT NULL DEFAULT '0.1000',
  `offer1688Title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weightSource` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `excelRef` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mark` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sizeText` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'workbench',
  `weightText` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pricing_records_createdAt_idx` (`createdAt`),
  KEY `pricing_records_sku_idx` (`sku`),
  KEY `pricing_records_excelRef_idx` (`excelRef`)
) ENGINE=InnoDB AUTO_INCREMENT=358 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

