DROP TABLE IF EXISTS `product_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_metrics` (
  `id` int NOT NULL AUTO_INCREMENT,
  `productId` int NOT NULL,
  `taskId` int DEFAULT NULL,
  `soldCount` int DEFAULT NULL,
  `soldSum` decimal(14,2) DEFAULT NULL,
  `drr` decimal(6,2) DEFAULT NULL,
  `daysWithTrafarets` int DEFAULT NULL,
  `convToCartPdp` decimal(6,2) DEFAULT NULL,
  `convToCartSearch` decimal(6,2) DEFAULT NULL,
  `cancelRate` decimal(6,2) DEFAULT NULL,
  `createDays` int DEFAULT NULL,
  `rating` decimal(3,2) DEFAULT NULL,
  `reviewsCount` int DEFAULT NULL,
  `capturedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `product_metrics_productId_capturedAt_idx` (`productId`,`capturedAt`),
  KEY `product_metrics_taskId_idx` (`taskId`),
  CONSTRAINT `product_metrics_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `product_metrics_taskId_fkey` FOREIGN KEY (`taskId`) REFERENCES `collect_tasks` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=281 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

