DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sku` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categoryPath` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category3Name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUB',
  `sellerId` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sellerName` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sellerCountry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isChinaSeller` tinyint(1) NOT NULL DEFAULT '0',
  `imageUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `productUrl` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rating` decimal(3,2) DEFAULT NULL,
  `reviewsCount` int NOT NULL DEFAULT '0',
  `salesSchema` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sizeLengthMm` int DEFAULT NULL,
  `sizeWidthMm` int DEFAULT NULL,
  `sizeHeightMm` int DEFAULT NULL,
  `sizeWeightG` int DEFAULT NULL,
  `soldCount` int DEFAULT NULL,
  `soldSum` decimal(14,2) DEFAULT NULL,
  `drr` decimal(6,2) DEFAULT NULL,
  `daysWithTrafarets` int DEFAULT NULL,
  `convToCartPdp` decimal(6,2) DEFAULT NULL,
  `convToCartSearch` decimal(6,2) DEFAULT NULL,
  `cancelRate` decimal(6,2) DEFAULT NULL,
  `createDays` int DEFAULT NULL,
  `daysInPromo` int DEFAULT NULL,
  `discount` decimal(6,2) DEFAULT NULL,
  `raw` json DEFAULT NULL,
  `firstSeenAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `lastSeenAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_sku_key` (`sku`),
  KEY `products_category3Name_idx` (`category3Name`),
  KEY `products_soldCount_idx` (`soldCount`),
  KEY `products_createDays_idx` (`createDays`),
  KEY `products_lastSeenAt_idx` (`lastSeenAt`)
) ENGINE=InnoDB AUTO_INCREMENT=254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
